insert into public.lessons (id, unit_id, sort_order, kind) values ('9d91f7c3-b248-5ff6-ad88-27faa3f1a224', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'pre-a1' and u.slug = 'name-age-origin'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9d91f7c3-b248-5ff6-ad88-27faa3f1a224', 'vi', 'Bạn đến từ đâu?', 'Câu khẳng định: You are from Vietnam. Câu hỏi: đảo are lên trước you thành Are you from Vietnam? Tên nước và tên thành phố luôn viết hoa chữ đầu.', 'Đọc rõ âm cuối /m/ trong from. Nối âm: I''m from đọc liền, hai âm /m/ gần nhau chỉ cần ngậm môi một lần.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9d91f7c3-b248-5ff6-ad88-27faa3f1a224', 'en-US', 'Where are you from?', 'Statement: You are from Vietnam. Question: put are before you: Are you from Vietnam? Names of countries and cities start with a capital letter.', 'Say the last sound /m/ in from. Link the words in I''m from.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
